```rust
// Human-readable rendering of a path for messages only. The result is never
// used to touch the filesystem -- the original OsStr is always used for that.
//
// A path that is valid UTF-8 and contains no ASCII control bytes, double
// quote, or backslash is shown verbatim. Any other path is shown in double
// quotes with escapes so the message stays a single line, cannot inject
// terminal control sequences, and keeps distinct raw names distinguishable:
//   \n  \r  \t          for newline, carriage return, tab
//   \"  \\              for double quote and backslash
//   \xhh                for any other ASCII control byte and for each raw
//                       byte that is not part of a valid UTF-8 sequence
//                       (hh = two lowercase hex digits)
// All other characters, including non-ASCII text such as Chinese, are kept
// as-is. Because a literal backslash in the real name is shown as \\, an
// escaped form can never be mistaken for a different file whose name
// literally contains the escape text.
fn display_path(path: &OsStr) -> String {
    let bytes = path.as_encoded_bytes();
    let plain = std::str::from_utf8(bytes)
        .map(|s| !s.bytes().any(needs_escape))
        .unwrap_or(false);
    if plain {
        return String::from_utf8(bytes.to_vec()).unwrap();
    }
    let mut out = String::with_capacity(bytes.len() + 2);
    out.push('"');
    let mut i = 0;
    while i < bytes.len() {
        let b = bytes[i];
        match b {
            b'\n' => out.push_str("\\n"),
            b'\r' => out.push_str("\\r"),
            b'\t' => out.push_str("\\t"),
            b'"' => out.push_str("\\\""),
            b'\\' => out.push_str("\\\\"),
            0x00..=0x1f | 0x7f => push_hex_escape(&mut out, b),
            0x20..=0x7e => out.push(b as char),
            _ => match decode_utf8_char(&bytes[i..]) {
                Some((ch, len)) => {
                    out.push(ch);
                    i += len - 1;
                }
                None => push_hex_escape(&mut out, b),
            },
        }
        i += 1;
    }
    out.push('"');
    out
}

fn needs_escape(b: u8) -> bool {
    b < 0x20 || b == 0x7f || b == b'"' || b == b'\\'
}

fn push_hex_escape(out: &mut String, b: u8) {
    const HEX: &[u8; 16] = b"0123456789abcdef";
    out.push_str("\\x");
    out.push(HEX[(b >> 4) as usize] as char);
    out.push(HEX[(b & 0xf) as usize] as char);
}

// Decode the UTF-8 character starting at bytes[0], if one is complete and
// valid. Returns the character and its length in bytes.
fn decode_utf8_char(bytes: &[u8]) -> Option<(char, usize)> {
    let len = match bytes[0] {
        0xc2..=0xdf => 2,
        0xe0..=0xef => 3,
        0xf0..=0xf4 => 4,
        _ => return None,
    };
    let s = std::str::from_utf8(bytes.get(..len)?).ok()?;
    s.chars().next().map(|ch| (ch, len))
}
```

